mapper.update:
UPDATE couple
SET profile_message = #{profileMessage}
WHERE inviter_id = #{memberId}
   OR invitee_id = #{memberId}

mapper.delete:
DELETE FROM couple
WHERE id = #{coupleId}
  AND (inviter_id = #{memberId} OR invitee_id = #{memberId})

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM couple
    WHERE inviter_id = #{memberId}
       OR invitee_id = #{memberId}
)

mapper.insert:
INSERT INTO couple (
    inviter_id,
    invitee_id,
    invitation_code_id
) VALUES (
    #{inviterId},
    #{inviteeId},
    #{invitationCodeId}
)
